using System.ComponentModel;
using System.IO;
using System.Windows;
using BG3PakViewer.Contracts;
using BG3PakViewer.Locales;
using BG3PakViewer.Shared.Extensions;
using HanumanInstitute.MvvmDialogs;
using Microsoft.Win32;
using Serilog;

namespace BG3PakViewer.Services;

/// <summary>
///     Exports the content generated by a preview to a folder the user picks.
/// </summary>
/// <param name="appSettings"></param>
/// <param name="dialogService"></param>
internal sealed class PreviewExportService(IAppSettings appSettings, IDialogService dialogService)
    : IPreviewExportService
{
    /// <summary>
    ///     Asks the user for a target folder and writes the given files there.
    /// </summary>
    /// <param name="files">The files to export.</param>
    public async Task ExportAsync(IReadOnlyList<PreviewExportFile> files)
    {
        if (files.Count == 0) return;

        var dialog = new OpenFolderDialog
        {
            InitialDirectory = Directory.Exists(appSettings.DefaultExportDirectory)
                ? appSettings.DefaultExportDirectory
                : string.Empty
        };
        if (dialog.ShowDialog() != true)
        {
            Log.Information("Preview export folder selection was cancelled");
            return;
        }

        var exported = 0;
        foreach (var file in files)
        {
            var path = Path.Combine(dialog.FolderName, file.FileName);
            try
            {
                await using var source = await file.OpenAsync();
                await using var target = File.Create(path);
                await source.CopyToAsync(target);
                exported++;
            }
            catch (Exception ex)
            {
                Log.Error(ex, "Failed to export file to: {Path}", path);
            }
        }

        Log.Information("Exported {Exported} of {Total} files", exported, files.Count);
        if (Application.Current.MainWindow?.DataContext is not INotifyPropertyChanged owner) return;
        if (exported == files.Count)
            await dialogService.ShowMessageBoxNotifyAsync(owner, Strings.ExportCompleted, Strings.ExportCompleted,
                MessageBoxIcon.Success);
        else
            await dialogService.ShowMessageBoxNotifyAsync(owner, Strings.ExportFailedMessage,
                Strings.ExportFailedCaption, MessageBoxIcon.Error);
    }
}